-- 1. Проверка каскадного обновления: меняем ID 1-го факультета на 100
UPDATE faculties SET faculty_id = 100 WHERE faculty_id = 1;
-- Проверяем: в таблице groups у групп 101 и 102 значение faculty_id само изменилось на 100
SELECT * FROM groups WHERE faculty_id = 100;

-- 2. Проверка каскадного удаления: удаляем факультет с ID = 100
DELETE FROM faculties WHERE faculty_id = 100;
-- Проверяем: группы 101 и 102 автоматически удалились из таблицы groups
SELECT * FROM groups;
